  cbse_note: 'CBSE-இன் பழைய CGPA முறையின் விதி (10ஆம் வகுப்பு கிரேடு ஷீட், ஏறக்குறைய 2010–2017): தோராயமான % = CGPA × 9.5. இது தோராயம் மட்டுமே, பல்கலைக்கழக CGPA-க்குப் பொருந்தாது. இப்போது CBSE மதிப்பெண்களைத் தருகிறது, மொத்த %-ஐ அறிவிப்பதில்லை.',
