  lbl_sgpa: 'SGPA', lbl_credits: 'மொத்த கிரெடிட்', lbl_points: 'கிரெடிட் புள்ளிகள்',
  s_sg1: 'ஒவ்வொரு பாடத்தின் கிரெடிட்டையும் அதன் கிரேடு புள்ளியால் பெருக்கிக் கூட்டுங்கள்.',
  s_sg2: 'கிரெடிட்களைக் கூட்டுங்கள்.',
  s_sg3: 'SGPA = மொத்த கிரெடிட் புள்ளிகள் ÷ மொத்த கிரெடிட்.',
  round_note: 'பல்கலைக்கழகங்கள் வெவ்வேறு விதமாக முழுமையாக்குகின்றன (சில 2 தசமங்களுக்குப் பின் வெட்டிவிடும்). சிறிது வேறுபட்டால் கிரேடு அட்டையின் மதிப்பை எடுங்கள்.',
  to_pct: 'இதை %-ஆக மாற்று',
  sem_title: 'உங்கள் செமஸ்டர்கள்',
  col_sem: 'செமஸ்டர்', col_sgpa: 'SGPA',
