  no_rows_sem: 'குறைந்தது ஒரு செமஸ்டரின் SGPA-ஐ உள்ளிடுங்கள்.',
  sm_mixed: 'ஒவ்வொரு செமஸ்டருக்கும் கிரெடிட் உள்ளிடுங்கள், அல்லது எளிய சராசரிக்கு எல்லா கிரெடிட்டையும் காலியாக விடுங்கள்.',
  ans_cgpa: 'CGPA = {g} ({n} செமஸ்டர்கள்)',
  lbl_sems: 'செமஸ்டர்கள்', lbl_simple: 'எளிய சராசரி',
  s_sm_avg: 'கிரெடிட் கொடுக்கப்படவில்லை, எனவே SGPA-களின் எளிய சராசரியை எடுங்கள்.',
  s_sm1: 'ஒவ்வொரு SGPA-ஐயும் அந்தச் செமஸ்டரின் கிரெடிட்டால் பெருக்கிக் கூட்டுங்கள்.',
