  sem_note: 'அதிக கிரெடிட் உள்ள செமஸ்டர்கள் அதிகம் கணக்கில் வரும். உங்கள் பல்கலைக்கழகம் எளிய சராசரி எடுத்தால் கிரெடிட்டைக் காலியாக விடுங்கள்.',
