  s_st_n: 'தள்ளுபடி {n}: {d}% குறைவு, அதாவது அப்போதைய விலையின் {k}% கொடுங்கள்.',
  s_st_save: 'மொத்தச் சேமிப்பு:',
  s_st_real: 'உண்மையான தள்ளுபடி = சேமிப்பு ÷ MRP × 100.',
  s_st_quick: 'விரைவு வழி: நீங்கள் கொடுக்கும் பகுதிகளைப் பெருக்குங்கள். நீங்கள் MRP-இன் {k} கொடுக்கிறீர்கள்.',
