  bg_q11: '1 வாங்கினால் 1 இலவசம்', bg_q21: '2 வாங்கினால் 1 இலவசம்', bg_q32: '3 வாங்கினால் 2 இலவசம்', bg_q150: '2வதுக்கு 50% தள்ளுபடி',
  s_bg1: 'நீங்கள் {b} + {g} பொருட்களை எடுக்கிறீர்கள்.',
  s_bg2_free: '{b} பொருட்களுக்கு மட்டுமே பணம் கொடுக்கிறீர்கள்; {g} இலவசம்.',
  s_bg2_off: 'கூடுதல் {g} பொருட்களுக்கு {o}% தள்ளுபடி: அதாவது {f} பொருட்கள் இலவசம். பணம் கொடுக்கும் பொருட்கள்:',
  s_bg3: 'பயனுள்ள தள்ளுபடி = இலவசப் பொருட்கள் ÷ அனைத்துப் பொருட்கள் × 100.',
  s_bg4: 'ஒரு பொருளின் விலை {p} என்றால்:',
