  un_help: 'இரண்டை மட்டும் ஒப்பிட ஒரு பேக்கைக் காலியாக விடுங்கள். எடையை எடையுடனும் (கிராம், கிலோ) கொள்ளளவைக் கொள்ளளவுடனும் (மி.லி., லிட்டர்) ஒப்பிடுங்கள்.',
  un_few: 'குறைந்தது இரண்டு பேக்குகளின் விலையும் அளவும் உள்ளிடுங்கள்.',
