  mm_note: 'மார்க்அப்பும் மார்ஜினும்: ₹80-க்கு வாங்கி ₹100-க்கு விற்றால், ₹20 லாபம் அடக்க விலையின் 25% (மார்க்அப்), ஆனால் விற்பனை விலையின் 20% (மார்ஜின்). பள்ளிக் கணிதம் (NCERT) லாபம் %-ஐ அடக்க விலையில் கணக்கிடுகிறது.',
