  s_pl1_0: 'SP − CP:',
  s_pl2_p: 'லாபம் % = லாபம் ÷ CP × 100.',
  s_pl2_l: 'நஷ்டம் % = நஷ்டம் ÷ CP × 100.',
  s_pl3: 'மார்ஜின் % = லாபம் ÷ SP × 100.',
  ans_tg_mu: 'அடக்க விலையில் {p} லாபத்திற்கு {sp}-க்கு விற்கவும் (லாபம் {a})',
  ans_tg_mg: '{p} மார்ஜினுக்கு {sp}-க்கு விற்கவும் (லாபம் {a})',
  s_tg_mu1: 'லாபம் = அடக்க விலையின் {p}%.',
  s_tg_mu2: 'SP = CP + லாபம்.',
  s_tg_also_mg: 'இது விற்பனை விலையில் {m} மார்ஜின்.',
  s_tg_mg1: '{p}% மார்ஜினில் அடக்க விலை விற்பனை விலையின் {k}%.',
