  s_cp1_p: '{p}% லாபத்தில் SP என்பது CP-இன் {k}%.',
  s_cp1_l: '{p}% நஷ்டத்தில் SP என்பது CP-இன் {k}%.',
  s_cp2: 'அதாவது CP (x)-இன் {k}% = SP. x-ஐக் கண்டறியுங்கள்.',
