  at_a: 'வந்த வகுப்புகள்', at_h: 'நடந்த வகுப்புகள்', at_t: 'தேவையான %', at_left: 'இந்தப் பருவத்தில் மீதமுள்ள வகுப்புகள் (விருப்பம்)',
  at_rule: 'CBSE பொதுத் தேர்வு (2025-26) எழுத 75% வருகையைக் கேட்கிறது; மருத்துவ அவசரம் போன்ற ஆவணமுள்ள காரணங்களுக்கு மட்டுமே தளர்வு. கல்லூரிகள் தங்கள் விதிகளை வைக்கின்றன: உங்கள் பள்ளி அல்லது கல்லூரியில் கேளுங்கள்.',
  err_att_over: 'வந்த வகுப்புகள் நடந்த வகுப்புகளை விட அதிகமாக இருக்க முடியாது.',
  lbl_att: 'இப்போதைய வருகை', lbl_need_row: 'தொடர்ந்து வர வேண்டியது', lbl_can_miss: 'தவறவிடலாம்',
  s_at1: 'வருகை = வந்தது ÷ நடந்தது × 100.',
  s_at2_need: 'அடுத்த n வகுப்புகளுக்குத் தவறாமல் வாருங்கள்: ({h} + n)-இல் ({a} + n) குறைந்தது {t}% இருக்க வேண்டும்.',
