  cu_help: 'ఈ సంఖ్యలను మీ విశ్వవిద్యాలయ నియమాల నుంచి లేదా మార్క్స్ మెమో నుంచి తీసుకోండి. చాలా విశ్వవిద్యాలయాలు × 10 వాడతాయి, కొన్ని (CGPA − 0.5) × 10 లేదా (CGPA − 0.75) × 10. మీది చూసుకోండి.',
  cbse_note: 'CBSE పాత CGPA విధానం నియమం (10వ తరగతి గ్రేడ్ షీట్, సుమారు 2010–2017): సూచిక % = CGPA × 9.5. ఇది అంచనా మాత్రమే, విశ్వవిద్యాలయ CGPA కి వర్తించదు. ఇప్పుడు CBSE మార్కులు ఇస్తుంది, మొత్తం % ప్రకటించదు.',
