  tip1: 'ಮೇಲೆ ಒಂದು ಟ್ಯಾಬ್ ಆರಿಸಿ (ಶೇಕಡಾ, ಅಂಕ %, CGPA, ರಿಯಾಯಿತಿ, ಲಾಭ-ನಷ್ಟ, ಹಾಜರಾತಿ), ನಂತರ ಪ್ರಶ್ನೆಯ ಪ್ರಕಾರ ಆರಿಸಿ. ಟೈಪ್ ಮಾಡುತ್ತಿದ್ದಂತೆ ಉತ್ತರ ಬದಲಾಗುತ್ತದೆ.',
  tip2: 'ಪ್ರತಿ ಉತ್ತರದಲ್ಲಿ NCERT ಪುಸ್ತಕಗಳಂತೆ ಬಿಡಿಸುವಿಕೆ ಕಾಣುತ್ತದೆ. ಸ್ಮಾರ್ಟ್‌ಬೋರ್ಡ್‌ನಲ್ಲಿ "ಪೂರ್ಣ ಪರದೆ" ಅಥವಾ ಉತ್ತರ ಕೀಲಿಗಾಗಿ "ಮುದ್ರಿಸಿ" ಬಳಸಿ.',
  tip3: 'ಅಂಗಡಿಗಾಗಿ: "50% + 20% ಕಡಿತ" ಸೇಲ್ ಅಥವಾ "2 ಕೊಂಡರೆ 1 ಉಚಿತ" ಆಫರ್ ಪರಿಶೀಲಿಸಿ, ಕೊಳ್ಳುವ ಮೊದಲು ಬೇರೆ ಬೇರೆ ಪ್ಯಾಕ್‌ಗಳ ಕೆಜಿ ಬೆಲೆ ಹೋಲಿಸಿ.',
  tip4: 'ವಿದ್ಯಾರ್ಥಿಗಳು: ವಿಷಯಗಳನ್ನು ಸೇರಿಸಿ ಶೇಕಡಾ, ಬೆಸ್ಟ್ ಆಫ್ 5 ಮತ್ತು ಮುಂದಿನ ಪರೀಕ್ಷೆಯಲ್ಲಿ ಬೇಕಾದ ಅಂಕ ನೋಡಿ. ಎಷ್ಟು ತರಗತಿ ತಪ್ಪಿಸಿದರೂ 75% ಇರುತ್ತದೆ ಎಂದೂ ನೋಡಿ.',
  tip5: 'ತರಗತಿ ಚಟುವಟಿಕೆ: ಪ್ರತಿ ಗುಂಪಿಗೆ ಒಂದು ಅಂಗಡಿ ಬಿಲ್ ಅಥವಾ ಅಂಕಪಟ್ಟಿ ನೀಡಿ; ಅವರು ನೋಟ್‌ಬುಕ್‌ನಲ್ಲಿ ಬಿಡಿಸಿ ಇಲ್ಲಿ ಹಂತಗಳನ್ನು ಪರಿಶೀಲಿಸುತ್ತಾರೆ.',
  tip6: 'ವಿಶ್ವವಿದ್ಯಾಲಯದ CGPA ಗೆ "ನನ್ನ ವಿಶ್ವವಿದ್ಯಾಲಯ" ಆರಿಸಿ ಅಂಕಪಟ್ಟಿಯಲ್ಲಿನ ಸೂತ್ರ ನಮೂದಿಸಿ. ನಿಮ್ಮ ಸಂಖ್ಯೆಗಳು ಈ ಸಾಧನದಲ್ಲೇ ಉಳಿಯುತ್ತವೆ; ಮರುಹೊಂದಿಸಿ ಉದಾಹರಣೆಗಳನ್ನು ಮರಳಿ ತರುತ್ತದೆ.'
