  cu_help: 'ഈ സംഖ്യകൾ നിങ്ങളുടെ സർവകലാശാലയുടെ നിയമങ്ങളിൽ നിന്നോ മാർക്ക് ലിസ്റ്റിൽ നിന്നോ എടുക്കുക. പല സർവകലാശാലകളും × 10 ഉപയോഗിക്കുന്നു, ചിലത് (CGPA − 0.5) × 10 അല്ലെങ്കിൽ (CGPA − 0.75) × 10. നിങ്ങളുടേത് പരിശോധിക്കുക.',
  cbse_note: 'CBSE-യുടെ പഴയ CGPA സംവിധാനത്തിലെ നിയമം (10-ാം ക്ലാസ് ഗ്രേഡ് ഷീറ്റ്, ഏകദേശം 2010–2017): സൂചക % = CGPA × 9.5. ഇത് ഏകദേശക്കണക്ക് മാത്രം, സർവകലാശാല CGPA-ക്ക് ബാധകമല്ല. ഇപ്പോൾ CBSE മാർക്ക് നൽകുന്നു, ആകെ % പ്രഖ്യാപിക്കുന്നില്ല.',
